  5	namespace Modules\AI\Domain\Intel;
  6	
  7	use Illuminate\Support\Facades\DB;
  8	use Symfony\Component\Yaml\Yaml;
  9	
 10	/**
 11	 * What a target has paid this account before: a bounded counter per player and coordinate, raised by a
 12	 * raid that came home with loot and lowered by one that came home empty (architecture step 7, 4.2).
 13	 *
 14	 * It is memory, not a forecast. Nothing here touches the host's world and nothing is derived from a live
 15	 * foreign planet: the writer is the account's own raid outcome, recorded from the host's battle report,
 16	 * and the reader is the scout that ranks its next probe. The counter outlives the process in `ai_intel`,
 17	 * so a session an hour later still knows what a farm did. The step, the bound and the weight the counter
 18	 * carries into a ranking are read by name from `resources/behavior/intel.yaml`, never written here.
 19	 */
 20	final class IntelBook
 21	{
 22	    private const POLICY_FILE = '/resources/behavior/intel.yaml';
 23	
 24	    /** @var array<string, mixed>|null */
 25	    private static ?array $policy = null;
 26	
 27	    /** The key a target is written and read under: the three numbers every report carries. */
 28	    public static function key(int $galaxy, int $system, int $position): string
 29	    {
 30	        return $galaxy . ':' . $system . ':' . $position;
 31	    }
 32	
 33	    /** The current score of one target: zero for a planet the account has never fought. */
 34	    public function priority(int $playerId, string $coordinate): int
 35	    {
 36	        $priority = DB::table('ai_intel')
 37	            ->where('player_id', $playerId)
 38	            ->where('coordinate', $coordinate)
 39	            ->value('priority');
 40	
 41	        return $priority === null ? 0 : (int) $priority;
 42	    }
 43	
 44	    /**
 45	     * Every target this account has a counter for, keyed by coordinate: the read side of a ranking board
 46	     * where a coordinate the account never hit is simply absent, so a caller reads a missing key as zero.
 47	     *
 48	     * @return array<string, int>
 49	     */
 50	    public function priorities(int $playerId): array
 51	    {
 52	        $priorities = [];
 53	        foreach (DB::table('ai_intel')->where('player_id', $playerId)->get(['coordinate', 'priority']) as $row) {
 54	            $priorities[(string) $row->coordinate] = (int) $row->priority;
 55	        }
 56	
 57	        return $priorities;
 58	    }
 59	
 60	    /**
 61	     * Fold one raid outcome into a target's counter: a profitable raid raises it, a loss lowers it, and the
 62	     * counter stops at the bound either way. Returns the counter as it now stands.
 63	     */
 64	    public function recordOutcome(int $playerId, string $coordinate, bool $won): int
 65	    {
 66	        $existing = DB::table('ai_intel')->where('player_id', $playerId)->where('coordinate', $coordinate)->value('priority');
 67	        $priority = $this->bounded(($existing === null ? 0 : (int) $existing) + ($won ? $this->step('win_step') : -$this->step('loss_step')));
 68	
 69	        $where = ['player_id' => $playerId, 'coordinate' => $coordinate];
 70	
 71	        if ($existing === null) {
 72	            DB::table('ai_intel')->insert($where + [
 73	                'priority' => $priority,
 74	                'last_outcome_at' => now(),
 75	                'created_at' => now(),
 76	                'updated_at' => now(),
 77	            ]);
 78	
 79	            return $priority;
 80	        }
 81	
 82	        DB::table('ai_intel')->where($where)->update([
 83	            'priority' => $priority,
 84	            'last_outcome_at' => now(),
 85	            'updated_at' => now(),
 86	        ]);
 87	
 88	        return $priority;
 89	    }
 90	
 91	    private function step(string $name): int
 92	    {
 93	        return max(1, $this->int('target_priority.' . $name, 1));
 94	    }
 95	
 96	    private function bounded(int $priority): int
 97	    {
 98	        return max($this->int('target_priority.floor', $priority), min($this->int('target_priority.ceiling', $priority), $priority));
 99	    }
100	
101	    private function int(string $path, int $fallback): int
102	    {
103	        return (int) $this->number($path, (float) $fallback);
104	    }
105	
106	    private function number(string $path, float $fallback): float
107	    {
108	        $value = $this->policy();
109	
110	        foreach (explode('.', $path) as $segment) {
111	            $value = is_array($value) ? ($value[$segment] ?? null) : null;
112	        }
113	
114	        return is_numeric($value) ? (float) $value : $fallback;
115	    }
116	
117	    /** @return array<string, mixed> */
118	    private function policy(): array
119	    {
120	        if (self::$policy !== null) {
121	            return self::$policy;
122	        }
123	
124	        $path = dirname(__DIR__, 3) . self::POLICY_FILE;
125	        $parsed = is_file($path) ? Yaml::parseFile($path) : [];
126	
127	        return self::$policy = is_array($parsed) ? $parsed : [];
128	    }
129	}

