  5	namespace Modules\AI\Domain\Galaxy;
  6	
  7	use Illuminate\Support\Collection;
  8	use Illuminate\Support\Facades\DB;
  9	use Modules\AI\Infrastructure\Battle\NativeRaidEstimator;
 10	use OGame\Models\EspionageReport;
 11	use OGame\Models\Message;
 12	use OGame\Models\Resources;
 13	use OGame\Services\ObjectService;
 14	use Symfony\Component\Yaml\Yaml;
 15	use Throwable;
 16	
 17	/**
 18	 * What one system looks like from the account's own intel: how much military it has seen standing there
 19	 * (threat) and how much loot its reports showed (opportunity), so a colony site or an errand can be chosen
 20	 * with an eye on the neighbourhood instead of blind (architecture step 7, 4.5).
 21	 *
 22	 * Only what the account has been told counts. The reports are reached through the account's own inbox
 23	 * rows, the same link every other intel reader uses, so nothing here reads a live foreign planet
 24	 * (diagnosis 2.5) and no object is named: the units a report lists are priced through the host's own
 25	 * catalogue and its resources through the estimator's weights. The window, the scale, the bound and the
 26	 * share open loot is worth are read by name from `resources/behavior/intel.yaml`.
 27	 */
 28	final class GalaxyMap
 29	{
 30	    private const POLICY_FILE = '/resources/behavior/intel.yaml';
 31	
 32	    /** @var array<string, mixed>|null */
 33	    private static ?array $policy = null;
 34	
 35	    /** The military this account has seen in one system, in map points; zero for a system it never probed. */
 36	    public function threat(int $playerId, int $galaxy, int $system): int
 37	    {
 38	        $value = 0.0;
 39	        foreach ($this->seen($playerId, $galaxy, $system) as $report) {
 40	            $value += $this->unitsValue($report->ships ?? []) + $this->unitsValue($report->defense ?? []);
 41	        }
 42	
 43	        return $this->points($value);
 44	    }
 45	
 46	    /** The loot this account has seen in one system, in map points, discounted for the fights it sits behind. */
 47	    public function opportunity(int $playerId, int $galaxy, int $system): int
 48	    {
 49	        $value = 0.0;
 50	        foreach ($this->seen($playerId, $galaxy, $system) as $report) {
 51	            $value += $this->isDefended($report) ? $this->lootValue($report) * $this->share('galaxy_map.defended_opportunity_share') : $this->lootValue($report);
 52	        }
 53	
 54	        return $this->points($value);
 55	    }
 56	
 57	    /**
 58	     * The reports this account has received on the system, newest per position: the map is the account's
 59	     * last look at a body, not the sum of every probe it has ever sent.
 60	     *
 61	     * @return Collection<int, EspionageReport>
 62	     */
 63	    private function seen(int $playerId, int $galaxy, int $system): Collection
 64	    {
 65	        $reportIds = Message::query()
 66	            ->where('user_id', $playerId)
 67	            ->whereNotNull('espionage_report_id')
 68	            ->where('created_at', '>=', now()->subHours($this->int('galaxy_map.report_window_hours', 168)))
 69	            ->pluck('espionage_report_id');
 70	
 71	        if ($reportIds->isEmpty()) {
 72	            return collect();
 73	        }
 74	
 75	        return EspionageReport::query()
 76	            ->whereIn('id', $reportIds)
 77	            ->where('planet_galaxy', $galaxy)
 78	            ->where('planet_system', $system)
 79	            ->orderByDesc('id')
 80	            ->get(['planet_position', 'resources', 'ships', 'defense'])
 81	            ->unique('planet_position')
 82	            ->values();
 83	    }
 84	
 85	    /** @param array<string, int>|null $units */
 86	    private function unitsValue(?array $units): float
 87	    {
 88	        $value = 0.0;
 89	
 90	        foreach ($units ?? [] as $machineName => $amount) {
 91	            $value += $this->unitValue((string) $machineName) * (float) $amount;
 92	        }
 93	
 94	        return $value;
 95	    }
 96	
 97	    /**
 98	     * One hull on the estimator's own weights. A report can name a hull the universe no longer has, which
 99	     * prices at nothing rather than failing the whole read.
100	     */
101	    private function unitValue(string $machineName): float
102	    {
103	        try {
104	            return app(NativeRaidEstimator::class)->metalEquivalent(ObjectService::getObjectRawPrice($machineName));
105	        } catch (Throwable) {
106	            return 0.0;
107	        }
108	    }
109	
110	    private function lootValue(EspionageReport $report): float
111	    {
112	        $resources = $report->resources ?? [];
113	
114	        return app(NativeRaidEstimator::class)->metalEquivalent(new Resources(
115	            (int) ($resources['metal'] ?? 0),
116	            (int) ($resources['crystal'] ?? 0),
117	            (int) ($resources['deuterium'] ?? 0),
118	        ));
119	    }
120	
121	    /** [] is "probed and empty": loot standing in the open, not loot behind a fight. */
122	    private function isDefended(EspionageReport $report): bool
123	    {
124	        return ($report->ships ?? []) !== [] || ($report->defense ?? []) !== [];
125	    }
126	
127	    /**
128	     * The metal-equivalent of a system in map points, bounded: the scale keeps a rich system and a poor one
129	     * apart, the ceiling stops one report from dwarfing the map, and no system ever reads below zero.
130	     */
131	    private function points(float $value): int
132	    {
133	        $scale = max(1, $this->int('galaxy_map.scale', 10_000));
134	
135	        return max(0, (int) min($this->int('galaxy_map.ceiling', PHP_INT_MAX), (int) floor($value / $scale)));
136	    }
137	
138	    private function share(string $path): float
139	    {
140	        return max(0.0, min(1.0, $this->number($path, 0.0)));
141	    }
142	
143	    private function int(string $path, int $fallback): int
144	    {
145	        return (int) $this->number($path, (float) $fallback);
146	    }
147	
148	    private function number(string $path, float $fallback): float
149	    {
150	        $value = $this->policy();
151	
152	        foreach (explode('.', $path) as $segment) {
153	            $value = is_array($value) ? ($value[$segment] ?? null) : null;
154	        }
155	
156	        return is_numeric($value) ? (float) $value : $fallback;
157	    }
158	
159	    /** @return array<string, mixed> */
160	    private function policy(): array
161	    {
162	        if (self::$policy !== null) {
163	            return self::$policy;
164	        }
165	
166	        $path = dirname(__DIR__, 3) . self::POLICY_FILE;
167	        $parsed = is_file($path) ? Yaml::parseFile($path) : [];
168	
169	        return self::$policy = is_array($parsed) ? $parsed : [];
170	    }
171	}

