 3	namespace Modules\AI\Actions;
 4	
 5	use Modules\AI\Domain\Intel\IntelBook;
 6	use Modules\AI\Enums\AiExperienceCaseFamily;
 7	use Modules\AI\Enums\AiExperienceFeatureVersion;
 8	use Modules\AI\Enums\AiExperienceOutcome;
 9	use Modules\AI\Enums\AiExperienceRulesetVersion;
10	use Modules\AI\Enums\AiRaidExperienceFeature;
11	use Modules\AI\Models\AiExperienceCase;
12	use OGame\Models\BattleReport;
13	
14	/**
15	 * Turns a raid's committed battle report into a raid-outcome experience case.
16	 *
17	 * The loot figure is the host's own `loot` column on the report — the resources
18	 * the attacker actually captured, never a module estimate. The case is keyed by
19	 * the target's coordinates so the raid planner can later blacklist a target the
20	 * account keeps coming home empty from.
21	 */
22	class RecordAiRaidOutcomeAction
23	{
24	    public function handle(int $playerId, int $observationId, BattleReport $report): AiExperienceCase|null
25	    {
26	        $loot = $report->loot ?? [];
27	        if ($loot === []) {
28	            return null;
29	        }
30	
31	        $metalEquivalent = (float) ($loot['metal'] ?? 0)
32	            + 1.5 * (float) ($loot['crystal'] ?? 0)
33	            + 2.0 * (float) ($loot['deuterium'] ?? 0);
34	
35	        $outcome = $metalEquivalent > 0 ? AiExperienceOutcome::Succeeded : AiExperienceOutcome::Failed;
36	
37	        app(IntelBook::class)->recordOutcome(
38	            $playerId,
39	            IntelBook::key((int) $report->planet_galaxy, (int) $report->planet_system, (int) $report->planet_position),
40	            $metalEquivalent > 0,
41	        );
42	
43	        return app(RecordAiExperienceOutcomeAction::class)->handle(
44	            $playerId,
45	            $observationId,
46	            AiExperienceCaseFamily::Raid,
47	            $outcome,
48	            AiExperienceFeatureVersion::RaidV1->value,
49	            AiExperienceRulesetVersion::HostBattleReportLootV1->value,
50	            [
51	                AiRaidExperienceFeature::Galaxy->value => (int) $report->planet_galaxy,
52	                AiRaidExperienceFeature::System->value => (int) $report->planet_system,
53	                AiRaidExperienceFeature::Position->value => (int) $report->planet_position,
54	                AiRaidExperienceFeature::Loot->value => $metalEquivalent,
55	            ],
56	            $metalEquivalent > 0 ? 1.0 : 0.0,
57	            0,
58	        );
59	    }
60	}

