 17	abstract class TestCase extends BaseTestCase
 18	{
 19	    /**
 20	     * Fail quickly when a test tries to wait on an InnoDB row lock or MySQL metadata lock.
 21	     *
 22	     * These are session settings, so they must be applied after Laravel has selected the
 23	     * per-worker parallel test database connection.
 24	     */
 25	    protected function setUp(): void
 26	    {
 27	        parent::setUp();
 28	
 29	        // No test may reach a real outbound service. An unmocked request throws here instead of
 30	        // spending money or returning something the assertion never expected, and a test that
 31	        // wants a response fakes it. This is what keeps the module's provider path honest: it stays
 32	        // enabled exactly as production runs it, and the boundary is what is faked.
 33	        Http::preventStrayRequests();
 34	
 35	        // OGAMEX_TEST_NOW stands the whole run at one instant (e.g. 2026-10-07T03:00:00Z). Unset, the wall
 36	        // clock decides as before. The AI module's clock-sweep runs a test at several hours with it to find
 37	        // a test whose outcome depends on the time of day.
 38	        $frozenNow = getenv('OGAMEX_TEST_NOW');
 39	        if ($frozenNow !== false && trim($frozenNow) !== '') {
 40	            $at = CarbonImmutable::parse(trim($frozenNow));
 41	            Date::setTestNow($at);
 42	            Carbon::setTestNow($at);
 43	            CarbonImmutable::setTestNow($at);
 44	        }
 45	
 46	        if ($this->app->environment('testing') && DB::getDriverName() === 'mysql') {
 47	            DB::unprepared('SET SESSION innodb_lock_wait_timeout = 1');
 48	            DB::unprepared('SET SESSION lock_wait_timeout = 1');
 49	        }
 50	    }
 51	
 52	    /**
 53	     * Creates the application.
 54	     *
 55	     * @return Application
 56	     */
 57	    public function createApplication(): Application
 58	    {
 59	        $app = require __DIR__ . '/../bootstrap/app.php';
 60	
 61	        // Ignition records every query, model and log line for its error pages. That
 62	        // recorder costs milliseconds per query, which dwarfs the work under test (the
 63	        // whole suite runs roughly ten times faster without it). Error pages keep the
 64	        // recorders outside the test environment.
 65	        $app->afterBootstrapping(LoadConfiguration::class, function (Application $app): void {
 66	            $app['config']->set('ignition.recorders', []);
 67	        });
 68	
 69	        $app->make(Kernel::class)->bootstrap();
 70	
 71	        return $app;
 72	    }
 73	
 74	    /**
 75	     * Find an empty coordinate near the given anchor using the shared collision-safe test logic.
 76	     */
 77	    protected function getSafeEmptyCoordinate(
 78	        Coordinate $anchor,
 79	        int $minPosition = 4,
 80	        int $maxPosition = 12,
 81	        int $minSystemDistance = 0
 82	    ): Coordinate {
 83	        $settingsService = resolve(SettingsService::class);
 84	        $maxGalaxies = $settingsService->numberOfGalaxies();
 85	
 86	        $galaxy = $anchor->galaxy <= $maxGalaxies ? $anchor->galaxy : 1;
 87	        $coordinate = new Coordinate($galaxy, 0, 0);
 88	        $tryCount = 0;
 89	
 90	        while ($tryCount < 100) {
 91	            $tryCount++;
 92	
 93	            do {
 94	                $offset = rand(-10, 10);
 95	            } while ($minSystemDistance > 0 && abs($offset) < $minSystemDistance);
 96	
 97	            $coordinate->system = max(1, min(499, $anchor->system + $offset));
 98	            $coordinate->position = rand($minPosition, $maxPosition);
 99	
100	            $planetCount = DB::table('planets')
101	                ->where('galaxy', $coordinate->galaxy)
102	                ->where('system', $coordinate->system)
103	                ->where('planet', $coordinate->position)
104	                ->count();
105	
106	            if ($planetCount === 0) {
107	                return $coordinate;
108	            }
109	        }
110	
111	        $this->fail('Failed to find an empty coordinate for testing.');
112	    }
113	}

