 21	/**
 22	 * Base class for tests that require an authenticated account, isolated per test.
 23	 *
 24	 * Wraps each test in a database transaction (DatabaseTransactions) so no rows leak between
 25	 * tests and tests no longer depend on execution order. Creates the user via the standard
 26	 * Eloquent factories (User::factory()) + actingAs() instead of a real HTTP /register +
 27	 * /login round-trip, and starts the session up-front so csrf_token() returns a real token
 28	 * (CSRF stays fully enforced).
 29	 *
 30	 * Shared test helpers are grouped into focused traits in Tests\Traits (planet state,
 31	 * page assertions, build requests, messages and foreign fixtures).
 32	 */
 33	abstract class IsolatedAccountTestCase extends TestCase
 34	{
 35	    use DatabaseTransactions;
 36	    use ManagesPlanetState;
 37	    use AssertsPageState;
 38	    use SubmitsBuildRequests;
 39	    use AssertsMessages;
 40	    use CreatesForeignFixtures;
