 69	    /**
 70	     * Set up common test components.
 71	     */
 72	    protected function setUp(): void
 73	    {
 74	        parent::setUp();
 75	
 76	        // Set default test time to 2024-01-01 00:00:00 to ensure all tests have the same starting point.
 77	        $this->travelTo(Date::create(2024, 1, 1, 0, 0, 0));
 78	
 79	        // Set default server settings for all tests.
 80	        $settingsService = resolve(SettingsService::class);
 81	        $settingsService->set('economy_speed', 8);
 82	        // Establish a full speed baseline so settings mutated by earlier tests can't leak
 83	        // into this one. Without this, e.g. ResearchQueueTest sets research_speed=2 which
 84	        // then changes timing in unrelated tests like VacationModeTest (see #1021).
 85	        $settingsService->set('research_speed', 1);
 86	
 87	        // Set amount of planets to be created for the user because planet switching
 88	        // is a part of the test suite.
