 92	        // This ensures tests don't fail when the database has planets in galaxies
 93	        // beyond the configured max (e.g., from previous test runs with different settings).
 94	        $maxGalaxies = $settingsService->numberOfGalaxies();
 95	        $lastAssignedGalaxy = (int)$settingsService->get('last_assigned_galaxy', 1);
 96	        if ($lastAssignedGalaxy > $maxGalaxies) {
 97	            $settingsService->set('last_assigned_galaxy', 1);
 98	            $settingsService->set('last_assigned_system', 1);
 99	        }
100	
101	        // Create a new user and login so we can access ingame features.
102	        $this->createAndLoginUser();
103	
104	        // Start the session up-front so csrf_token() returns a real token.
105	        $this->app['session']->driver()->start();
106	    }
107	
108	    /**
109	     * Refreshing the application creates a connection outside this test's transaction,
110	     * making its fixtures unavailable. Remove the underlying cache dependency before
111	     * converting a test that needs this behavior.
112	     */
113	    final public function reloadApplication(): void
114	    {
115	        throw new LogicException('reloadApplication() is incompatible with IsolatedAccountTestCase.');
116	    }
