160	     */
161	    protected function createUser(): User
162	    {
163	        // Create without model events to skip the `created` hook that promotes the first
164	        // user to admin. That hook issues a cross-row `update users`, which contends with
165	        // the scheduler/queue worker and deadlocks (1205 lock wait) in tests.
166	        $user = User::withoutEvents(fn (): User => User::factory()->create([
167	            'username' => 'test_' . Str::random(16),
168	        ]));
169	
170	        resolve(InitialUserDataService::class)->createFor($user);
171	
172	        return $user;
173	    }
