 20	/**
 21	 * Reduces one committed battle report into observations for the AIs that took part.
 22	 *
 23	 * The report is the legal visibility boundary: it is the same stored row every
 24	 * participant can already read in game, and it names the planet owner and the attacking
 25	 * player. Nothing else about the battle is read, and a player who was not one of those
 26	 * two is never given an observation.
 27	 */
 28	class RecordObservedBattleReportAction
 29	{
 30	    /**
 31	     * A campaign consults after this many faction fleet losses: the second defeat is the
 32	     * moment an experienced player stops repeating the same defence and reconsiders.
 33	     */
 34	    private const REPEATED_SETBACK_LOSSES = 2;
 35	
 36	    public function __construct(private readonly AiClock $clock)
 37	    {
 38	    }
 39	
 40	    public function handle(int $battleReportId): int
 41	    {
 42	        /** @var BattleReport|null $battleReport */
 43	        $battleReport = BattleReport::query()->find($battleReportId);
 44	
 45	        if ($battleReport === null) {
 46	            return 0;
 47	        }
 48	
 49	        $defenderPlayerId = $this->playerId($battleReport->planet_user_id);
 50	        $attackerPlayerId = $this->playerId($this->attackerSide($battleReport)['player_id'] ?? null);
 51	
 52	        // A report naming one side only, or the same player twice, is a shape this
 53	        // reducer does not understand; it declines instead of guessing who was harmed.
 54	        if ($defenderPlayerId === null || $attackerPlayerId === null || $defenderPlayerId === $attackerPlayerId) {
 55	            return 0;
 56	        }
 57	
 58	        return DB::transaction(fn (): int => $this->recordObservations(
 59	            $battleReport,
 60	            $defenderPlayerId,
 61	            $attackerPlayerId,
 62	        ));
 63	    }
 64	
 65	    private function recordObservations(BattleReport $battleReport, int $defenderPlayerId, int $attackerPlayerId): int
 66	    {
 67	        $this->signalCampaignEvents($battleReport, $defenderPlayerId, $attackerPlayerId);
 68	
 69	        /** @var array<int, int> $counterparties Each participant maps to the player it faced. */
 70	        $counterparties = [
 71	            $defenderPlayerId => $attackerPlayerId,
 72	            $attackerPlayerId => $defenderPlayerId,
 73	        ];
 74	
 75	        $participants = AiProfile::query()
 76	            ->where('enabled', true)
 77	            ->whereIn('player_id', array_keys($counterparties))
 78	            ->pluck('player_id')
 79	            ->map(fn (mixed $playerId): int => (int) $playerId)
 80	            ->all();
 81	
 82	        $recorded = 0;
 83	
 84	        foreach ($participants as $playerId) {
 85	            // The unique source identity makes retrying an after-commit callback safe.
 86	            $observation = AiObservation::firstOrCreateAtomically([
 87	                'player_id' => $playerId,
 88	                'source_type' => AiObservationSource::BattleReport,
 89	                'source_id' => $battleReport->id,
 90	            ], [
 91	                'kind' => AiObservationKind::BattleReportObserved,
 92	                'subject_player_id' => $counterparties[$playerId],
 93	                'source_time' => $battleReport->created_at ?? $this->clock->now(),
 94	                'observed_at' => $this->clock->now(),
 95	            ]);
 96	
 97	            if (!$observation->wasRecentlyCreated) {
 98	                continue;
 99	            }
100	
101	            // The appraisal asks the affect sidecar; it runs on the queue so no login waits on it (step 6).
102	            AppraiseAiBattleReport::dispatch($observation->id);
103	
104	            $recorded++;
105	        }
106	
107	        $this->recordRaidLoot($battleReport, $attackerPlayerId, $participants);
108	        $this->recordAllyUnderAttackObservations($battleReport, $defenderPlayerId, $attackerPlayerId);
109	
110	        return $recorded;
111	    }
112	
113	    /**
114	     * The raid-outcome experience case for the attacker, when this account was
115	     * the raider: the host's own loot column becomes taste over the target, so a
116	     * repeatedly empty farm is later blacklisted instead of re-screened forever.
117	     *
118	     * @param array<int, int> $participants
119	     */
120	    private function recordRaidLoot(BattleReport $battleReport, int $attackerPlayerId, array $participants): void
121	    {
122	        if (!in_array($attackerPlayerId, $participants, true)) {
123	            return;
124	        }
125	
126	        $observation = AiObservation::query()
127	            ->where('player_id', $attackerPlayerId)
128	            ->where('source_type', AiObservationSource::BattleReport)
129	            ->where('source_id', $battleReport->id)
130	            ->first();
131	
132	        if ($observation === null) {
133	            return;
134	        }
135	
136	        app(RecordAiRaidOutcomeAction::class)->handle($attackerPlayerId, $observation->id, $battleReport);
137	    }
138	
139	    /**
140	     * A committed attack on an alliance co-member is the trigger DEF-003 named for ACS-defend:
141	     * the defender's AI co-members observe it, so a later defend decision has an
142	     * "ally under attack" fact to act on. The defender itself already got a
143	     * BattleReportObserved observation, and a defender with no alliance has no one to warn.
144	     */
145	    private function recordAllyUnderAttackObservations(BattleReport $battleReport, int $defenderPlayerId, int $attackerPlayerId): void
146	    {
147	        $allianceId = User::query()->whereKey($defenderPlayerId)->value('alliance_id');
148	
149	        if ($allianceId === null) {
150	            return;
151	        }
152	
153	        $allyIds = AiProfile::query()
154	            ->where('enabled', true)
155	            ->where('player_id', '!=', $defenderPlayerId)
156	            ->whereIn('player_id', User::query()->where('alliance_id', $allianceId)->select('id'))
157	            ->pluck('player_id');
158	
159	        foreach ($allyIds as $allyId) {
160	            $observation = AiObservation::firstOrCreateAtomically([
161	                'player_id' => $allyId,
162	                'source_type' => AiObservationSource::BattleReport,
163	                'source_id' => $battleReport->id,
164	            ], [
165	                'kind' => AiObservationKind::AllyUnderAttack,
166	                'subject_player_id' => $attackerPlayerId,
167	                'source_time' => $battleReport->created_at ?? $this->clock->now(),
168	                'observed_at' => $this->clock->now(),
169	            ]);
170	
171	            if (!$observation->wasRecentlyCreated) {
172	                continue;
173	            }
174	
175	            $occurredAt = CarbonImmutable::instance($battleReport->created_at ?? $this->clock->now());
176	
177	            // An ally attacked is a shared enemy: the observer marks the attacker, and grows
178	            // closer to the ally it now shares a front with. Repeated attacks accumulate,
179	            // which is what turns an incident into a lasting side (the WW2 bloc reflex).
180	            app(RecordAiRelationshipInteractionAction::class)->handle(
181	                $allyId,
182	                $attackerPlayerId,
183	                $observation->id,
184	                $occurredAt,
185	                trustChange: -0.05,
186	                threatChange: 0.20,
187	                affinityChange: -0.05,
188	            );
189	
190	            app(RecordAiRelationshipInteractionAction::class)->handle(
191	                $allyId,
192	                $defenderPlayerId,
193	                $observation->id,
194	                $occurredAt,
195	                affinityChange: 0.10,
196	                socialImportanceChange: 0.05,
197	            );
198	        }
199	    }
