201	    /**
202	     * Turns a committed battle into its campaign signals: coalition infighting when both sides
203	     * are coalition, and a faction fleet loss — cascading to a repeated setback — when the one
204	     * faction side was wiped out. Both stay campaign-scoped and are consumed by the next faction
205	     * session decision, never here.
206	     */
207	    private function signalCampaignEvents(BattleReport $battleReport, int $defenderPlayerId, int $attackerPlayerId): void
208	    {
209	        $factionIds = AiProfile::query()
210	            ->where('enabled', true)
211	            ->whereIn('player_id', [$defenderPlayerId, $attackerPlayerId])
212	            ->pluck('player_id')
213	            ->map(fn (mixed $playerId): int => (int) $playerId)
214	            ->all();
215	
216	        $attackerIsFaction = in_array($attackerPlayerId, $factionIds, true);
217	        $defenderIsFaction = in_array($defenderPlayerId, $factionIds, true);
218	        $at = CarbonImmutable::instance($battleReport->created_at ?? $this->clock->now());
219	
220	        if (!$attackerIsFaction && !$defenderIsFaction) {
221	            $this->signalActiveCampaigns(AiCampaignConsultationTrigger::CoalitionConflict, $at);
222	
223	            return;
224	        }
225	
226	        // A faction-faction battle is ordinary play, never a campaign fleet loss.
227	        if ($attackerIsFaction === $defenderIsFaction) {
228	            return;
229	        }
230	
231	        if (!$this->sideWiped($battleReport, $attackerIsFaction ? 'attacker' : 'defender')) {
232	            return;
233	        }
234	
235	        $this->signalFleetLoss($at);
236	    }
237	
238	    private function signalFleetLoss(CarbonImmutable $at): void
239	    {
240	        foreach (AiCampaign::query()->where('state', AiCampaignState::Active)->get(['id']) as $campaign) {
241	            app(RecordCampaignConsultationSignalAction::class)->handle(
242	                $campaign->id,
243	                AiCampaignConsultationTrigger::FleetLoss,
244	                $at,
245	            );
246	
247	            // ponytail: the counter reads FleetLoss signals, so losses that pile up before a
248	            // session consumes the open signal collapse into one row and the count can read
249	            // low. OGame defeats are minutes apart at the fastest and a session follows each,
250	            // so the undercount has no practical ceiling worth a dedicated counter table.
251	            $losses = AiCampaignConsultationSignal::query()
252	                ->where('campaign_id', $campaign->id)
253	                ->where('trigger', AiCampaignConsultationTrigger::FleetLoss->value)
254	                ->count();
255	
256	            if ($losses >= self::REPEATED_SETBACK_LOSSES) {
257	                app(RecordCampaignConsultationSignalAction::class)->handle(
258	                    $campaign->id,
259	                    AiCampaignConsultationTrigger::RepeatedSetback,
260	                    $at,
261	                );
262	            }
263	        }
264	    }
265	
266	    private function signalActiveCampaigns(AiCampaignConsultationTrigger $trigger, CarbonImmutable $at): void
267	    {
268	        foreach (AiCampaign::query()->where('state', AiCampaignState::Active)->pluck('id') as $campaignId) {
269	            app(RecordCampaignConsultationSignalAction::class)->handle($campaignId, $trigger, $at);
270	        }
271	    }
