273	    /**
274	     * The faction side was wiped out when the last round leaves it zero ships and the opposing
275	     * side survivors. An empty round list is an uncontested arrival, not a fleet loss.
276	     */
277	    private function sideWiped(BattleReport $battleReport, string $side): bool
278	    {
279	        $rounds = is_array($battleReport->rounds) ? $battleReport->rounds : [];
280	
281	        if ($rounds === []) {
282	            return false;
283	        }
284	
285	        $lastRound = $rounds[array_key_last($rounds)];
286	        $attacker = $this->shipAmount($lastRound['attacker_ships'] ?? null);
287	        $defender = $this->shipAmount($lastRound['defender_ships'] ?? null);
288	
289	        return $side === 'attacker'
290	            ? $attacker === 0 && $defender > 0
291	            : $defender === 0 && $attacker > 0;
292	    }
293	
294	    private function shipAmount(mixed $units): int
295	    {
296	        $total = 0;
297	
298	        if (!is_array($units)) {
299	            return $total;
300	        }
301	
302	        foreach ($units as $amount) {
303	            $total += is_numeric($amount) ? (int) $amount : 0;
304	        }
305	
306	        return $total;
307	    }
308	
309	    /** @return array<string, mixed> */
310	    private function attackerSide(BattleReport $battleReport): array
311	    {
312	        return is_array($battleReport->attacker) ? $battleReport->attacker : [];
313	    }
314	
315	    private function playerId(mixed $value): int|null
316	    {
317	        // The host names a deleted or abandoned account with a non-positive sentinel (-1, -2,
318	        // 0); a report naming one has no real counterparty, so it is declined instead of being
319	        // recorded with a subject id that overflows the unsigned column.
320	        return is_numeric($value) && (int) $value > 0 ? (int) $value : null;
321	    }
