 26	/**
 27	 * Answers whether this account can probe a neighbour now, and which one.
 28	 *
 29	 * Scouting is the ordinary first contact an experienced player makes with the
 30	 * galaxies around them, and it is what turns "no target intel" into the reports
 31	 * raids later depend on. The target is a foreign planet the account does not own
 32	 * and whose owner is neither in vacation mode nor the protected administrator —
 33	 * the same gates the host's own espionage mission applies — and the probe the
 34	 * mission consumes is the ship the host requires. The candidate list is the
 35	 * host's own planets table, so no target is named here.
 36	 *
 37	 * A target the account already holds fresh intel on, or already has a probe in
 38	 * flight toward, is skipped. Scouting is bounded: each neighbour is probed once
 39	 * per intel window, and the account waits for its own probe to come back before
 40	 * sending another instead of re-probing the same planets it cannot act on.
 41	 */
 42	class QueueableSpyPlanner
 43	{
 44	    /** Bounded: only this many unscouted, nearest candidate targets are inspected per decision. */
 45	    private const MAX_CANDIDATES = 20;
 46	
 47	    /** A report stays fresh this long; scouting and raiding agree on the window. */
 48	    private const INTEL_TTL_HOURS = 24;
 49	
 50	    /** A partial report on a valuable target gets this many probes; the host redacts ships below two and defence below three probes, so one probe re-reads the same redacted report. */
 51	    private const ESCALATED_PROBES = 5;
 52	
 53	    /** Metal-equivalent loot that makes a redacted report worth a probe volley. */
 54	    private const RICH_YIELD = 10_000.0;
 55	
 56	    public function __construct(
 57	        private PlayerServiceFactory $playerServiceFactory,
 58	        private PlanetServiceFactory $planetServiceFactory,
 59	        private ActivityIntelReader $activityIntelReader,
 60	        private IntelBook $intelBook,
 61	    ) {
 62	    }
 63	
 64	    public function plan(int $playerId, ?PlayerService $player = null): ?QueueableSpy
 65	    {
 66	        $profile = AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->first();
 67	        if ($profile === null) {
 68	            return null;
 69	        }
 70	
 71	        if (!User::query()->whereKey($playerId)->exists()) {
 72	            return null;
 73	        }
 74	
 75	        $player ??= $this->playerServiceFactory->make($playerId, true);
 76	
 77	        $skip = $this->freshIntelCoordinates($playerId)
 78	            + $this->inFlightCoordinates($playerId)
 79	            + $this->openSpyIntentCoordinates($playerId);
 80	        $selection = $this->target($player, $skip);
 81	        if ($selection === null) {
 82	            return null;
 83	        }
 84	        [$origin, $target] = $selection;
 85	
 86	        return app()->makeWith(QueueableSpy::class, [
 87	            'planetId' => $origin->getPlanetId(),
 88	            'targetGalaxy' => (int) $target->galaxy,
 89	            'targetSystem' => (int) $target->system,
 90	            'targetPosition' => (int) $target->planet,
 91	            'targetType' => (int) $target->planet_type,
 92	            'missionType' => EspionageMission::getTypeId(),
 93	            'probeCount' => $this->probeCount($target),
 94	        ]);
 95	    }
 96	
 97	    /**
 98	     * Every own planet whose idle probes still exceed what its own pending spy intents
 99	     * have committed (N6). A probe already promised to a queued or retried intent is not a
100	     * second probe, so two pending probes for different targets each plan from the budget
101	     * that remains after the other is committed.
102	     *
103	     * @return list<PlanetService>
104	     */
105	    private function idleProbePlanets(PlayerService $player): array
106	    {
107	        $committed = $this->committedProbesByPlanet($player->getId());
108	        $probeName = EspionageMission::getRequiredShipMachineNames()[0];
109	        $planets = [];
110	
111	        foreach ($player->planets->all() as $planet) {
112	            $idle = $planet->getShipUnits()->getAmountByMachineName($probeName);
113	
114	            if ($idle > ($committed[$planet->getPlanetId()] ?? 0)) {
115	                $planets[] = $planet;
116	            }
117	        }
118	
119	        return $planets;
120	    }
121	
122	    /** @return array<int, int> probes committed to open spy intents, keyed by the origin planet */
123	    private function committedProbesByPlanet(int $playerId): array
124	    {
125	        $committed = [];
126	
127	        foreach (AiWorkItem::query()
128	            ->where('player_id', $playerId)
129	            ->where('kind', AiWorkKind::Spy)
130	            ->whereIn('state', [AiWorkState::Pending, AiWorkState::Leased, AiWorkState::Retry])
131	            ->get(['payload']) as $item) {
132	            $payload = $item->payload ?? [];
133	            $planetId = (int) ($payload['planet_id'] ?? 0);
134	
135	            if ($planetId > 0) {
136	                $committed[$planetId] = ($committed[$planetId] ?? 0) + 1;
137	            }
138	        }
139	
140	        return $committed;
141	    }
142	
143	    /**
144	     * The best legal foreign target, scored instead of the first one in id order.
145	     *
146	     * Own, destroyed, vacationing and administrator-protected planets are all
147	     * skipped — the module restates no rule, it only declines candidates the
148	     * host's own mission would refuse. A planet the account already knows, or
149	     * already has a probe travelling toward, is skipped too. Among what remains,
150	     * a just-touched target is skipped (INT-009) and the rest are ranked by
151	     * known yield, what the target paid before and closeness (INT-003): the
152	     * closest known-rich neighbour, not the lowest id.
153	     *
154	     * @param array<string, true> $skipCoordinates
155	     * @return array{0: PlanetService, 1: Planet}|null the origin and its target
156	     */
157	    private function target(PlayerService $player, array $skipCoordinates): ?array
158	    {
159	        $idleOrigins = $this->idleProbePlanets($player);
160	        if ($idleOrigins === []) {
161	            return null;
162	        }
163	
164	        // A scout reads the neighbours nearest to home, not the oldest stamps in the universe: ordering by the
165	        // owner's last login pushed every cohort account (whose stamp is zero) behind the fixed farms, so
166	        // the nearest rivals were never read and nothing defended was ever raided. The farm-first ranking
167	        // below still picks the quiet body among the nearest, and the host's isInactive() stays the authority.
168	        $home = $idleOrigins[0]->getPlanetCoordinates();
169	        $candidates = Planet::query()
170	            ->leftJoin('users', 'users.id', '=', 'planets.user_id')
171	            ->where('planets.user_id', '!=', $player->getId())
172	            ->where('planets.destroyed', 0)
173	            ->where(fn ($owner) => $owner->whereNull('users.vacation_mode')->orWhere('users.vacation_mode', 0))
174	            ->whereIn('planets.planet_type', [PlanetType::Planet->value, PlanetType::Moon->value])
175	            ->select('planets.*')
176	            ->orderByRaw('ABS(CAST(`planets`.`galaxy` AS SIGNED) - ?) * 100000 + ABS(CAST(`planets`.`system` AS SIGNED) - ?) * 20 + ABS(CAST(`planets`.`planet` AS SIGNED) - ?), `planets`.`id`', [$home->galaxy, $home->system, $home->position])
177	            ->cursor()
178	            ->reject(static fn (Planet $planet): bool => isset($skipCoordinates["{$planet->galaxy}:{$planet->system}:{$planet->planet}"]))
179	            ->take(self::MAX_CANDIDATES)
180	            ->values();
181	
182	        $intel = $this->knownIntelByCoordinate($candidates);
183	        $knownYield = $intel['yield'];
184	        // What the account remembers about these planets: the priority counter, read in one pass so a
185	        // target that paid before is not priced once per candidate.
186	        $priorities = $this->intelBook->priorities($player->getId());
187	        $payoffWeight = $this->intelBook->probeRankWeight();
188	        $fighter = $this->ownsWarFleet($idleOrigins);
189	        $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
190	        $scored = [];
191	
192	        foreach ($candidates as $planet) {
193	            $coordinateKey = "{$planet->galaxy}:{$planet->system}:{$planet->planet}";
194	            if (isset($skipCoordinates[$coordinateKey])) {
195	                continue;
196	            }
197	
198	            // The candidate model is already in hand; building a PlanetService
199	            // from it skips the per-candidate Planet::find + refreshUser that
200	            // make($id, true) would pay (20 candidates × 2 round trips).
201	            $target = $this->planetServiceFactory->makeFromModel($planet);
202	
203	            $owner = $target->getPlayer();
204	
205	            // The host's own protected-administrator signal, so the rule survives any operator rename.
206	            if ($owner?->isAdmin() === true) {
207	                continue;
208	            }
209	            $origin = $this->closestOrigin($idleOrigins, $planet, $fleetMissions);
210	            $distance = $fleetMissions->calculateFleetMissionDistance($origin, new Coordinate((int) $planet->galaxy, (int) $planet->system, (int) $planet->planet));
211	            $scored[] = [
212	                'planet' => $planet,
213	                'origin' => $origin,
214	                'inactive' => $owner?->isInactive() ?? false,
215	                'quiet' => !$this->activityIntelReader->activityAt($target),
216	                'defended' => $fighter && isset($intel['defended'][$coordinateKey]),
217	                'score' => ($knownYield[$coordinateKey] ?? 0.0) - $distance + $payoffWeight * ($priorities[$coordinateKey] ?? 0),
218	            ];
219	        }
220	
221	        if ($scored === []) {
222	            return null;
223	        }
224	
225	        // The farm comes first, then the neighbour away from the keyboard, then the one at it: a player who
226	        // has read every quiet body still scouts the active ones, since an account that acts every few
227	        // minutes is the only kind that fights back and leaves debris. Among equals the closest known-rich
228	        // body wins (INT-003).
229	        // An account that owns a war fleet reads the bodies known to fight back first: an administrator
230	        // sees raids that pillage empty planets as a dead universe (LIFE_FIGHTS), and a fleet is built
231	        // to be flown at something that shoots.
232	        usort($scored, static fn (array $left, array $right): int => [$right['defended'], $right['inactive'], $right['quiet'], $right['score']] <=> [$left['defended'], $left['inactive'], $left['quiet'], $left['score']]);
233	
234	        return [$scored[0]['origin'], $scored[0]['planet']];
235	    }
