237	    /**
238	     * Whether any scouting base stands a military hull, by the host's own military catalogue.
239	     *
240	     * @param list<PlanetService> $origins
241	     */
242	    private function ownsWarFleet(array $origins): bool
243	    {
244	        $military = array_map(static fn ($ship): string => $ship->machine_name, ObjectService::getMilitaryShipObjects());
245	
246	        foreach ($origins as $origin) {
247	            foreach ($origin->getShipUnits()->units as $entry) {
248	                // A probe is in the military catalogue but carries no real weapon: a war fleet shoots.
249	                $player = $origin->getPlayer();
250	                if ($player !== null && in_array($entry->unitObject->machine_name, $military, true) && $entry->unitObject->properties->attack->calculate($player)->totalValue > 1) {
251	                    return true;
252	                }
253	            }
254	        }
255	
256	        return false;
257	    }
258	
259	    /**
260	     * The own planet with an idle probe closest to the target, not the first in
261	     * collection order: a probe is fuel and time, so the nearest base sends it.
262	     *
263	     * @param list<PlanetService> $origins
264	     */
265	    private function closestOrigin(array $origins, Planet $target, FleetMissionService $fleetMissions): PlanetService
266	    {
267	        $coordinate = new Coordinate((int) $target->galaxy, (int) $target->system, (int) $target->planet);
268	        $best = $origins[0];
269	        $bestDistance = $fleetMissions->calculateFleetMissionDistance($best, $coordinate);
270	
271	        foreach ($origins as $origin) {
272	            $distance = $fleetMissions->calculateFleetMissionDistance($origin, $coordinate);
273	            if ($distance < $bestDistance) {
274	                $best = $origin;
275	                $bestDistance = $distance;
276	            }
277	        }
278	
279	        return $best;
280	    }
281	
282	    /**
283	     * The probes this target is worth. A complete report refreshes with one; a
284	     * partial report on a defended or known-rich body gets a volley — the host
285	     * redacts ships below two probes and defence below three, so one probe is
286	     * how the account keeps re-reading the same redacted report forever. An
287	     * empty redaction stays at one: the probes are not worth it.
288	     */
289	    private function probeCount(Planet $target): int
290	    {
291	        $report = EspionageReport::query()
292	            ->where('planet_galaxy', $target->galaxy)
293	            ->where('planet_system', $target->system)
294	            ->where('planet_position', $target->planet)
295	            ->orderByDesc('id')
296	            ->first(['resources', 'ships', 'defense']);
297	
298	        if ($report === null) {
299	            return 1;
300	        }
301	
302	        if ($this->activityIntelReader->completenessFactor($report->ships, $report->defense) >= 1.0) {
303	            return 1;
304	        }
305	
306	        if (!$this->isDefended($report->ships, $report->defense) && $this->yieldFromResources($report->resources ?? []) < self::RICH_YIELD) {
307	            return 1;
308	        }
309	
310	        return self::ESCALATED_PROBES;
311	    }
312	
313	    /**
314	     * @param array<string, int>|null $ships
315	     * @param array<string, int>|null $defense
316	     */
317	    private function isDefended(array|null $ships, array|null $defense): bool
318	    {
319	        return ($ships ?? []) !== [] || ($defense ?? []) !== [];
320	    }
321	
322	    /**
323	     * The last-known loot of each candidate, as metal-equivalent, from its most
324	     * recent report of any age. A never-probed planet scores zero here and is
325	     * ranked by closeness alone.
326	     *
327	     * Also says which of them the last report found defended (ships or defence standing), since the
328	     * scout that owns a war fleet reads the bodies that fight before the empty farms.
329	     *
330	     * @param iterable<int, Planet> $candidates
331	     * @return array{yield: array<string, float>, defended: array<string, true>}
332	     */
333	    private function knownIntelByCoordinate(iterable $candidates): array
334	    {
335	        $planets = is_array($candidates) ? $candidates : iterator_to_array($candidates);
336	        if ($planets === []) {
337	            return ['yield' => [], 'defended' => []];
338	        }
339	
340	        // One pass over the candidate coordinates instead of one report read per
341	        // candidate: the newest report per coordinate wins, so keep the first
342	        // (highest id) seen on the descending-id sweep.
343	        $reports = EspionageReport::query()
344	            ->where(function ($query) use ($planets): void {
345	                foreach ($planets as $planet) {
346	                    $query->orWhere(function ($coordinate) use ($planet): void {
347	                        $coordinate->where('planet_galaxy', $planet->galaxy)
348	                            ->where('planet_system', $planet->system)
349	                            ->where('planet_position', $planet->planet);
350	                    });
351	                }
352	            })
353	            ->orderByDesc('id')
354	            ->get(['id', 'planet_galaxy', 'planet_system', 'planet_position', 'resources', 'ships', 'defense']);
355	
356	        $yield = [];
357	        $defended = [];
358	        foreach ($reports as $report) {
359	            $key = "{$report->planet_galaxy}:{$report->planet_system}:{$report->planet_position}";
360	            if (isset($yield[$key])) {
361	                continue;
362	            }
363	
364	            $yield[$key] = $this->yieldFromResources($report->resources ?? []);
365	            if ($this->isDefended($report->ships, $report->defense)) {
366	                $defended[$key] = true;
367	            }
368	        }
369	
370	        return ['yield' => $yield, 'defended' => $defended];
371	    }
372	
373	    /**
374	     * Metal-equivalent of a report's visible resources, on the estimator's own weights.
375	     *
376	     * @param array<string, mixed> $resources
377	     */
378	    private function yieldFromResources(array $resources): float
379	    {
380	        return (float) ($resources['metal'] ?? 0)
381	            + 1.5 * (float) ($resources['crystal'] ?? 0)
382	            + 2.0 * (float) ($resources['deuterium'] ?? 0);
383	    }
384	
385	    /**
386	     * The coordinates the account already holds fresh intel on, keyed g:s:p.
387	     *
388	     * A report is reached through the account's own messages, the host's link
389	     * from a probe to the report it produced, and only reports inside the intel
390	     * window count. The window matches the observation service's TTL so scouting
391	     * and raiding agree on what "recently probed" means.
392	     *
393	     * @return array<string, true>
394	     */
395	    private function freshIntelCoordinates(int $playerId): array
396	    {
397	        $reportIds = Message::query()
398	            ->where('user_id', $playerId)
399	            ->whereNotNull('espionage_report_id')
400	            ->where('created_at', '>=', now()->subHours(self::INTEL_TTL_HOURS))
401	            ->pluck('espionage_report_id');
402	
403	        $coordinates = [];
404	        foreach (EspionageReport::query()->whereIn('id', $reportIds)->get(['planet_galaxy', 'planet_system', 'planet_position']) as $report) {
405	            $coordinates["{$report->planet_galaxy}:{$report->planet_system}:{$report->planet_position}"] = true;
406	        }
407	
408	        return $coordinates;
409	    }
